<?php declare(strict_types=1); namespace Annam; $title='Categories';$subtitle=count($records).' categories';$actions='<a class="o-btn o-btn-primary" href="/manage/categories/new/"><svg class="o-ic"><use href="#o-plus"/></svg>Add category</a>'; ?>
<nav class="o-meal-groups" aria-label="Category contents"><?php foreach(['populated'=>'With items','empty'=>'Empty categories','all'=>'All categories'] as $key=>$label):$count=count(array_filter($categories,fn($c)=>$key==='all'||($key==='empty'?$c['total']===0:$c['total']>0)));?><a class="<?= $scope===$key?'is-selected':'' ?>" href="?category_view=<?= e($key) ?>"><?= e($label) ?> <span><?= e($count) ?></span></a><?php endforeach;?></nav><p class="o-catalog-hint">Choose a category to manage its items. Empty categories are kept under Empty categories. Use the pencil button to edit category details.</p><form class="o-tools"><label class="o-search"><svg class="o-ic"><use href="#o-search"/></svg><input type="search" name="q" value="<?= e($query) ?>" placeholder="Search categories…" aria-label="Search categories"></label><input type="hidden" name="category_view" value="<?= e($scope) ?>"><noscript><button class="o-btn">Search</button></noscript></form>
<div class="o-table-wrap"><table class="o-table"><thead><tr><th></th><th>Name</th><th>Products</th><th>Visible</th><th><span class="o-sr">Actions</span></th></tr></thead><tbody data-stagger><?php foreach($records as $r):$items='/manage/categories/'.$r['id'].'/items/?status=1&stock=1';?><tr><td><a class="o-thumb" href="<?= e($items) ?>" tabindex="-1" aria-hidden="true"><?php if($r['image']):?><img src="<?= e(image_url($r['image'])) ?>" alt="" loading="lazy"><?php else:?><svg class="o-ic"><use href="#o-image"/></svg><?php endif;?></a></td><td><a class="o-row-title" href="<?= e($items) ?>"><?= e($r['name']) ?></a></td><td><a href="<?= e($items) ?>"><?= e($r['website']) ?> on website</a><small class="o-sub"><a href="/manage/categories/<?= e($r['id']) ?>/items/"><?= e($r['total']) ?> total including hidden items</a></small></td><td><form method="post" action="/manage/categories/<?= e($r['id']) ?>/toggle/"><?= csrf() ?><button class="o-switch <?= $r['active']?'is-on':'' ?>" type="submit" role="switch" aria-checked="<?= $r['active']?'true':'false' ?>" aria-label="<?= e('Toggle '.$r['name']) ?>"><i></i></button></form></td><td><div class="o-row-actions"><a class="o-icon-btn" aria-label="Manage items" href="<?= e($items) ?>"><svg class="o-ic"><use href="#o-grid"/></svg></a><a class="o-icon-btn" href="/manage/categories/<?= e($r['id']) ?>/" aria-label="<?= e('Edit category '.$r['name']) ?>"><svg class="o-ic"><use href="#o-edit"/></svg></a></div></td></tr><?php endforeach;?><?php if(!$records):?><tr><td colspan="5">No matching categories.</td></tr><?php endif;?></tbody></table></div>
